 if(order.proof){box.append(el('h2',`Korrektur version ${order.proof.version}`));box.append(el('p',`PF-reference: ${order.proof.reference}`));if(order.proof.mimeType){const download=el('a','Åbn original korrektur ↗','proof-file-link');download.href=`/api/pf-orders/${id}/proof-file?version=${order.proof.version}`;download.target='_blank';download.rel='noopener';box.append(download);}const preview=el('div',null,'preview');box.append(preview);if(order.proof.mimeType){try{const response=await api(`/api/pf-orders/${id}/proof-file?version=${order.proof.version}`),blob=await response.blob();previewUrl=URL.createObjectURL(blob);const media=document.createElement(order.proof.mimeType==='application/pdf'?'iframe':'img');media.src=previewUrl;media.title='PF-korrektur';preview.append(media);}catch(error){preview.append(el('p',error.message));}}else if(order.proof.url){const link=el('a','Åbn korrektur hos PF ↗');link.href=order.proof.url;link.target='_blank';link.rel='noopener noreferrer';preview.append(link);}}
